// mode_plasmoid() FX.cpp:7094
FXS.add("Plasmoid", function(S, E) {
	const plasmoip = E.s; // struct Plasphase {int16_t thisphase, thatphase;}
	const volumeSmth = S.audio().volumeSmth;
	S.fadeToBlackBy(32);
	plasmoip.thisphase = ((plasmoip.thisphase | 0) + beatsin8_t(6, -4, 4)) << 16 >> 16;
	plasmoip.thatphase = ((plasmoip.thatphase | 0) + beatsin8_t(7, -4, 4)) << 16 >> 16;
	for (let i = 0; i < S.len; i++) {
		let thisbright = cubicwave8((i * (1 + ((3 * S.speed) >> 5)) + plasmoip.thisphase) & 0xFF) >> 1;
		thisbright = (thisbright + (cos8_t((i * (97 + ((5 * S.speed) >> 5)) + plasmoip.thatphase) & 0xFF) >> 1)) & 0xFF;
		const colorIndex = thisbright;
		if (volumeSmth * S.intensity / 64 < thisbright) thisbright = 0;
		S.addPixelColor(i, color_blend(S.col[1], cfp(S, colorIndex), thisbright));
	}
}, AU);

// mode_puddles_base() FX.cpp:7125: Puddlepeak (peakdetect) and Puddles
function puddles_base(S, peakdetect) {
	const SEGLEN = S.len;
	if (SEGLEN <= 1) return fallback(S);
	let size = 0;
	const fadeVal = map(S.speed, 0, 255, 224, 254) & 0xFF;
	const pos = hw_random16(SEGLEN) >>> 0;
	S.fade_out(fadeVal);
	const A = S.audio();
	const volumeRaw = A.volumeRaw, samplePeak = A.samplePeak, volumeSmth = A.volumeSmth;
	if (peakdetect) { // puddles peak
		A.binNum = S.custom1;      // Select a bin.
		A.maxVol = S.custom2 >> 1; // Our volume comparator.
		if (samplePeak == 1) {
			size = (volumeSmth * S.intensity / 256 / 4 + 1) >>> 0;
			if (pos + size >= SEGLEN) size = SEGLEN - pos;
		}
	} else { // puddles
		if (volumeRaw > 1) {
			size = Math.trunc(Math.trunc(volumeRaw * S.intensity / 256) / 8) + 1;
			if (pos + size >= SEGLEN) size = SEGLEN - pos;
		}
	}
	for (let i = 0; i < size; i++) S.setPixelColor(pos + i, cfp(S, S.now));
}
