// mode_blurz() FX.cpp:7199 (1D only)
FXS.add("Blurz", function(S, E) {
	const SEGLEN = S.len;
	if (SEGLEN <= 1) return fallback(S);
	const fftResult = S.audio().fftResult;
	if (E.call == 0) {
		S.fill(BLACK);
		E.aux0 = 0;
	}
	const fadeoutDelay = (256 - S.speed) >> 5;
	if (fadeoutDelay <= 1 || (E.call % fadeoutDelay) == 0) S.fade_out(S.speed);
	E.step = (E.step + S.frametime) >>> 0;
	if (E.step > 5 + Math.floor(50 * (255 - S.speed) / SEGLEN)) { // SPEED_FORMULA_L FX.h:115
		const segLoc = hw_random16(SEGLEN);
		const f = fftResult[E.aux0 % 16];
		S.setPixelColor(segLoc, color_blend(S.col[1], cfp(S, Math.floor(2 * f * 240 / Math.max(1, SEGLEN - 1))), (2 * f) & 0xFF));
		E.aux0 = (E.aux0 + 1) % 16;
		E.step = 1;
		S.blur(S.intensity);
	}
}, AU);

// mode_DJLight() FX.cpp:7230
FXS.add("DJ Light", function(S, E) {
	const SEGLEN = S.len, mid = SEGLEN >> 1;
	const fftResult = S.audio().fftResult;
	if (E.call == 0) S.fill(BLACK);
	const secondHand = (secHand(S) + 1) & 0xFF; // C: .../500+1 % 64 == .../500 + 1
	if (E.aux0 != secondHand) {
		E.aux0 = secondHand;
		// CRGB(gamma8inv(fft[15]/2), gamma8inv(fft[5]/2), gamma8inv(fft[0]/2)).fadeToBlackBy(map(fft[4], 0, 255, 255, 4))
		const scale_fixed = 256 - (map(fftResult[4], 0, 255, 255, 4) & 0xFF);
		S.setPixelColor(mid, (gamma8inv(fftResult[15] >> 1) * scale_fixed) >> 8, (gamma8inv(fftResult[5] >> 1) * scale_fixed) >> 8, (gamma8inv(fftResult[0] >> 1) * scale_fixed) >> 8);
		for (let i = SEGLEN - 1; i > mid; i--) S.setPixelColor(i, S.getPixelColor(i - 1)); // move to the left
		for (let i = 0; i < mid; i++) S.setPixelColor(i, S.getPixelColor(i + 1));           // move to the right
	}
}, AU);

// mode_freqmap() FX.cpp:7259
FXS.add("Freqmap", function(S, E) {
	const SEGLEN = S.len;
	if (SEGLEN <= 1) return fallback(S);
	const A = S.audio();
	let FFT_MajorPeak = A.FFT_MajorPeak;
	const my_magnitude = A.my_magnitude / 4.0;
	if (FFT_MajorPeak < 1) FFT_MajorPeak = 1;
	if (E.call == 0) S.fill(BLACK);
	const fadeoutDelay = (256 - S.speed) >> 5;
	if (fadeoutDelay <= 1 || (E.call % fadeoutDelay) == 0) S.fade_out(S.speed);
	let locn = Math.trunc((Math.log10(FFT_MajorPeak) - 1.78) * SEGLEN / (MAX_FREQ_LOG10 - 1.78));
	if (locn < 1) locn = 0;
	if (locn >= SEGLEN) locn = SEGLEN - 1;
	let pixCol = Math.trunc((Math.log10(FFT_MajorPeak) - 1.78) * 255.0 / (MAX_FREQ_LOG10 - 1.78)) >>> 0;
	if (FFT_MajorPeak < 61.0) pixCol = 0;
	const bright = my_magnitude & 0xFF; // (uint8_t)float
	S.setPixelColor(locn, color_blend(S.col[1], cfp(S, S.intensity + pixCol), bright));
}, AU);

// Freqmatrix / Freqwave: CHSV(i, 240, gamma8inv(b)) from FFT_MajorPeak mapped between the Low and High bin sliders
function freqColor(S, FFT_MajorPeak, intensity) {
	if (FFT_MajorPeak > MAX_FREQUENCY) FFT_MajorPeak = 1;
	if (FFT_MajorPeak < 80) return BLACK;
	const upperLimit = 80 + 42 * S.custom2;
	const lowerLimit = 80 + 3 * S.custom1;
	const i = (lowerLimit != upperLimit ? map(Math.trunc(FFT_MajorPeak), lowerLimit, upperLimit, 0, 255) : FFT_MajorPeak) & 0xFF; // may under/overflow
	let b = Math.trunc(Math.min(255.0, 255.0 * intensity)) >>> 0;
	return CHSV(i, 240, gamma8inv(b));
}

// mode_freqmatrix() FX.cpp:7290
FXS.add("Freqmatrix", function(S, E) {
	const A = S.audio();
	const FFT_MajorPeak = A.FFT_MajorPeak, volumeSmth = A.volumeSmth;
	if (E.call == 0) S.fill(BLACK);
	const secondHand = (secHand(S) % 16) & 0xFF;
	if (E.aux0 != secondHand) {
		E.aux0 = secondHand;
		const sensitivity = map(S.custom3, 0, 31, 1, 10) & 0xFF;
		let pixVal = Math.trunc((volumeSmth * S.intensity * sensitivity) / 256.0);
		if (pixVal > 255) pixVal = 255;
		const intensity = map(pixVal, 0, 255, 0, 100) / 100.0;
		S.setPixelColor(0, freqColor(S, FFT_MajorPeak, intensity));
		for (let i = S.len - 1; i > 0; i--) S.setPixelColor(i, S.getPixelColor(i - 1)); // move to the left
	}
}, AU);

